def in2x2(g,r,c):
    col=g[r][c]; H,W=len(g),len(g[0])
    for rs in (r-1,r):
        for cs in (c-1,c):
            if 0<=rs and rs+1<H and 0<=cs and cs+1<W:
                if all(g[rs+i][cs+j]==col for i in(0,1) for j in(0,1)): return True
    return False
