def solve2(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    from collections import Counter
    for r in range(H):
        for c in range(W):
            col=g[r][c]
            nbrs=[]
            for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W: nbrs.append((dr,dc,out[rr][cc]))
            if any(v==col for _,v in nbrs): continue
            cnt=Counter(v for _,v in nbrs)
            best=max(cnt.values())
            cands={v for v,k in cnt.items() if k==best}
            pick=None
            for pref in ((0,1),(1,0),(-1,0),(0,-1)):
                for dr,dc,v in nbrs:
                    if (dr,dc)==pref and v in cands:
                        pick=v; break
                if pick is not None: break
            out[r][c]=pick
    return out
